from __future__ import annotations

import pytest

from llm_worker_pool.domain.token_estimate import (
    _CHARS_PER_TOKEN,
    estimate_tokens,
    max_chars_for_tokens,
)


@pytest.mark.parametrize(
    ("text", "expected"),
    [
        ("", 0),
        ("abcd", 1),
        ("abcdefgh", 2),
        ("abc", 0),
        ("abcdefghi", 2),
    ],
)
def test_estimate_tokens(text: str, expected: int) -> None:
    assert estimate_tokens(text) == expected


@pytest.mark.parametrize(
    ("tokens", "expected"),
    [
        (0, 0),
        (1, _CHARS_PER_TOKEN),
        (10, 10 * _CHARS_PER_TOKEN),
    ],
)
def test_max_chars_for_tokens(tokens: int, expected: int) -> None:
    assert max_chars_for_tokens(tokens) == expected
